using System.Collections;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
namespace Wildfolk.Tests
{
    public sealed class ContentExpansionPlayTests
    {
        private WorldSaveService save;private WorldGenerator world;private PlayerInventory player;
        [UnitySetUp]public IEnumerator Enter()
        {Time.timeScale=1;WorldGenerator.SelectedGenerationVersion=2;WorldGenerator.SelectedSeed=9472026;yield return SceneManager.LoadSceneAsync("Wildfolk");yield return null;yield return null;save=Object.FindFirstObjectByType<WorldSaveService>();save.AutoSaveEnabled=false;world=save.World;player=save.Player;save.Clock.enabled=false;player.GetComponent<PlayerMotor>().enabled=false;player.GetComponent<PlayerInputAdapter>().enabled=false;world.GetComponent<ZombieSpawner>().enabled=world.GetComponent<GoblinSpawner>().enabled=false;world.Chunks.DrainPending();}
        private void Move(Vector2 p){player.transform.position=p;player.GetComponent<Rigidbody2D>().position=p;Physics2D.SyncTransforms();world.Chunks.Reconcile();world.Chunks.DrainPending();}
        private int Give(string id,int count=1,int charges=0,LiquidState quality=LiquidState.Empty){var item=save.Catalog.Item(id);player.Model.Add(item,count,charges,quality);for(var i=0;i<player.Model.Capacity;i++)if(player.Model.GetSlot(i).Item==item){player.SelectSlot(i);return i;}Assert.Fail(id);return -1;}
        private Health Target()
        {var go=new GameObject("Combat target");go.SetActive(false);go.transform.position=player.transform.position+Vector3.right*5;var definition=ScriptableObject.CreateInstance<VitalityDefinition>();definition.MaximumHealth=100;var health=go.AddComponent<Health>();health.Definition=definition;go.AddComponent<CombatAffiliation>().Relation=EntityRelation.Hostile;go.AddComponent<CircleCollider2D>().radius=.6f;go.AddComponent<Rigidbody2D>().bodyType=RigidbodyType2D.Kinematic;go.SetActive(true);return health;}
        [UnityTest]public IEnumerator FishingRequiresNaturalWaterBiteAndSingleAuthoritativeReward()
        {
            Give("fishing_rod");var fishing=player.GetComponent<PlayerFishing>();Move(Vector2.zero);player.GetComponent<CharacterFacing>().Face(Vector2.right);Assert.That(fishing.Use(),Is.False);Move(new Vector2(world.Map.Continental.RiverAt(1000)+7,1000));player.GetComponent<CharacterFacing>().Face(Vector2.left);Assert.That(fishing.Use(),Is.True);Assert.That(fishing.Use(),Is.False);yield return new WaitForSeconds(3.1f);Assert.That(fishing.Phase,Is.EqualTo(FishingPhase.Bite));player.Model.Add(save.Catalog.Item("stone"),50*player.Model.Capacity);Assert.That(fishing.Use(),Is.False);var free=Enumerable.Range(0,player.Model.Capacity).First(i=>player.Model.GetSlot(i).Item==save.Catalog.Item("stone"));player.Model.ConsumeSlot(free,save.Catalog.Item("stone"),player.Model.GetSlot(free).Count);Assert.That(fishing.Use(),Is.True);Assert.That(fishing.Use(),Is.False);Assert.That(player.Model.CountItem(save.Catalog.Item("raw_fish")),Is.EqualTo(1));yield return new WaitForSeconds(.25f);var line=player.GetComponentInChildren<LineRenderer>();Assert.That(Vector2.Distance(line.GetPosition(2),player.transform.position),Is.LessThan(Vector2.Distance(fishing.WaterPoint,player.transform.position)));yield return null;
        }
        [UnityTest]public IEnumerator BowCrossbowConsumeMatchingAmmoAndHitEnemyWithoutMelee()
        {
            Move(new Vector2(0,-6));var target=Target();if(target==null)Assert.Fail("Animal fixture missing");target.transform.position=player.transform.position+Vector3.right*5;target.GetComponent<Rigidbody2D>().bodyType=RigidbodyType2D.Kinematic;target.GetComponent<Health>().RestoreHealth(target.GetComponent<Health>().Maximum);player.GetComponent<CharacterFacing>().Face(Vector2.right);Give("arrow",12);Give("bow");var ranged=player.GetComponent<PlayerRanged>();var hp=target.GetComponent<Health>().Current;Assert.That(ranged.Begin(),Is.True);Assert.That(player.GetComponent<PlayerCombat>().TryAttack(),Is.False);Assert.That(ranged.Begin(),Is.False);yield return new WaitForSeconds(.72f);Assert.That(player.Model.CountItem(save.Catalog.Item("arrow")),Is.EqualTo(11));Assert.That(ranged.Shots,Is.EqualTo(1));Assert.That(target.GetComponent<Health>().Current,Is.LessThan(hp));yield return new WaitForSeconds(.2f);Give("crossbow_bolt",12);Give("crossbow");Assert.That(ranged.Begin(),Is.True);yield return new WaitForSeconds(.2f);Assert.That(player.Model.CountItem(save.Catalog.Item("crossbow_bolt")),Is.EqualTo(11));Assert.That(ranged.Begin(),Is.False);
        }
        [UnityTest]public IEnumerator WaterskinThreeUsesChestDropAndSavePreserveQuality()
        {
            Move(new Vector2(world.Map.Continental.RiverAt(1000)+7,1000));var slot=Give("waterskin");var skin=player.GetComponent<PlayerWaterskin>();Assert.That(skin.Fill(),Is.True);Assert.That(player.SelectedStack.Charges,Is.EqualTo(3));var station=Object.Instantiate(save.Catalog.Item("campfire").Placement.Prefab,player.transform.position+Vector3.right*2,Quaternion.identity);var craft=player.GetComponent<PlayerCrafting>();Assert.That(craft.OpenStation(station.GetComponent<CraftingStation>()),Is.True);Assert.That(craft.Craft(save.Catalog.Recipe("purify_waterskin")),Is.EqualTo(CraftStatus.Processing));station.GetComponent<StationProcessing>().Advance(12);Assert.That(station.GetComponent<StationProcessing>().Collect(player),Is.True);world.Session.CloseInventory();player.GetComponent<PlayerSurvival>().Model.SetMeters(50,0);
            for(var i=0;i<3;i++){Assert.That(skin.Drink(),Is.True);yield return new WaitForSeconds(.51f);}Assert.That(player.SelectedStack.Charges,Is.Zero);Assert.That(skin.Drink(),Is.False);Assert.That(skin.Fill(),Is.True);player.Model.SetWater(slot,player.SelectedStack.Item,2,LiquidState.Clean);
            var chest=Object.Instantiate(save.Catalog.Item("storage_chest").Placement.Prefab,player.transform.position+Vector3.down*3,Quaternion.identity).GetComponent<StorageChest>();Assert.That(InventoryModel.Transfer(player.Model,slot,chest.Model,0),Is.True);var state=save.Capture();save.Validate(state);Assert.That(state.Placeables.Single(f=>f.Id==chest.Placeable.SaveId).Inventory[0].Charges,Is.EqualTo(2));Assert.That(InventoryModel.Transfer(chest.Model,0,player.Model,slot),Is.True);
            world.Session.OpenInventory();Assert.That(player.GetComponent<PlayerItemDrop>().Drop(player.Model,slot),Is.True);var drop=WorldPickup.Active.First(p=>p.Item==save.Catalog.Item("waterskin"));Assert.That(drop.Charges,Is.EqualTo(2));Assert.That(drop.Quality,Is.EqualTo(LiquidState.Clean));yield return null;
        }
        [UnityTest]public IEnumerator LanternHandsFreeAndCookingPotQueueSurviveValidatedSaveLoad()
        {
            Move(new Vector2(0,-6));var slot=Give("lantern");Assert.That(player.GetComponent<PlayerEquipment>().TryEquipFromSlot(slot),Is.True);Give("iron_pickaxe");yield return null;Assert.That(player.GetComponent<PlayerEquipment>().ActiveTool.Kind,Is.EqualTo(ToolKind.Pickaxe));Assert.That(player.GetComponent<PlayerLightSource>().Mount,Is.EqualTo(PlayerLightMount.Equipped));
            var pot=Object.Instantiate(save.Catalog.Item("cooking_pot").Placement.Prefab,new Vector2(2,-6),Quaternion.identity);foreach(var cost in save.Catalog.Recipe("mixed_stew").Ingredients)player.Model.Add(cost.Item,cost.Count);var craft=player.GetComponent<PlayerCrafting>();Assert.That(craft.OpenStation(pot.GetComponent<CraftingStation>()),Is.True);Assert.That(craft.Craft(save.Catalog.Recipe("mixed_stew")),Is.EqualTo(CraftStatus.Processing));world.Session.CloseInventory();var potId=pot.SaveId;var state=save.Capture();save.Validate(state);Assert.That(state.Player.Utility,Is.EqualTo("lantern"));save.Apply(SaveRepository.Decode(SaveRepository.Encode(state)));world.Chunks.DrainPending();yield return null;Assert.That(player.GetComponent<PlayerEquipment>().Utility.Id,Is.EqualTo("lantern"));var restored=WorldPlaceable.Active.Single(f=>f.SaveId==potId).GetComponent<StationProcessing>();restored.Advance(20);Assert.That(restored.Collect(player),Is.True);Assert.That(player.Model.CountItem(save.Catalog.Item("mixed_stew")),Is.EqualTo(1));
        }
        [UnityTest]public IEnumerator GatesCollideOpenAndTrapRespectsTeamAndCooldown()
        {
            Move(new Vector2(0,-6));var gate=Object.Instantiate(save.Catalog.Item("reinforced_gate").Placement.Prefab,new Vector2(3,-6),Quaternion.identity);var door=gate.GetComponent<WorldDoor>();Assert.That(door.Barrier.enabled,Is.True);Assert.That(door.Toggle(),Is.True);yield return new WaitForSeconds(.4f);Assert.That(door.Barrier.enabled,Is.False);Assert.That(door.Toggle(),Is.True);yield return new WaitForSeconds(.4f);Assert.That(door.Barrier.enabled,Is.True);
            var trap=Object.Instantiate(save.Catalog.Item("spike_trap").Placement.Prefab,player.transform.position,Quaternion.identity).GetComponent<SpikeTrap>();var hp=player.GetComponent<Health>().Current;yield return new WaitForSeconds(.1f);Assert.That(player.GetComponent<Health>().Current,Is.EqualTo(hp));var animal=Target();animal.transform.position=trap.transform.position;animal.GetComponent<Rigidbody2D>().bodyType=RigidbodyType2D.Kinematic;Physics2D.SyncTransforms();var before=animal.GetComponent<Health>().Current;yield return new WaitForSeconds(.1f);Assert.That(trap.Triggers,Is.EqualTo(1));var after=animal.GetComponent<Health>().Current;Assert.That(after,Is.LessThan(before));yield return new WaitForSeconds(.4f);Assert.That(animal.GetComponent<Health>().Current,Is.EqualTo(after));
        }
    }
}
